import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

let scene: THREE.Scene;
let camera: THREE.PerspectiveCamera;
let renderer: THREE.WebGLRenderer;
let cube: THREE.Mesh;
let orbit: OrbitControls;

let raycaster = new THREE.Raycaster();
let mouse = new THREE.Vector2();
let selectedFaceNormal: THREE.Vector3 | null = null;
let isDragging = false;
let startMouseX = 0;
let startMouseY = 0;
let startScale = new THREE.Vector3();
let hoveredFaceIndex: number | null = null;
let startPosition = new THREE.Vector3();

// 재질 배열 준비 (6개의 면을 위해)
const baseMaterial = new THREE.MeshBasicMaterial({
	color: 0xffffff,
	opacity: 0.5,
	transparent: true,
});
const highlightMaterial = new THREE.MeshBasicMaterial({
	color: 0xffff00,
	opacity: 1.0,
	transparent: true,
});
const materials = Array(6).fill(baseMaterial); // 6개의 면에 기본 재질 적용

// 축별 min/max 스케일 값 설정을 위한 인터페이스
interface AxisConstraints {
	x: { min: number; max: number };
	y: { min: number; max: number };
	z: { min: number; max: number };
}

export function init(
	div: HTMLDivElement,
	constraints: AxisConstraints = {
		x: { min: 1, max: 3 },
		y: { min: 1, max: 3 },
		z: { min: 1, max: 3 },
	},
) {
	// Scene & Camera
	scene = new THREE.Scene();
	camera = new THREE.PerspectiveCamera(70, div.clientWidth / div.clientHeight, 0.1, 100);
	camera.position.set(2, 2, 5);

	// Renderer
	renderer = new THREE.WebGLRenderer({ antialias: true });
	renderer.setSize(div.clientWidth, div.clientHeight);
	div.appendChild(renderer.domElement);

	// Cube (각 면을 별도의 그룹으로 처리)
	const geometry = new THREE.BoxGeometry(1, 1, 1);
	geometry.groups = [
		{ start: 0, count: 6, materialIndex: 0 }, // +X (right)
		{ start: 6, count: 6, materialIndex: 1 }, // -X (left)
		{ start: 12, count: 6, materialIndex: 2 }, // +Y (top)
		{ start: 18, count: 6, materialIndex: 3 }, // -Y (bottom)
		{ start: 24, count: 6, materialIndex: 4 }, // +Z (front)
		{ start: 30, count: 6, materialIndex: 5 }, // -Z (back)
	];
	cube = new THREE.Mesh(geometry, materials);
	scene.add(cube);

	// Light
	const light = new THREE.DirectionalLight(0xffffff, 1);
	light.position.set(5, 5, 5);
	scene.add(light);

	// OrbitControls
	orbit = new OrbitControls(camera, renderer.domElement);
	orbit.enableDamping = true;

	// Events
	window.addEventListener('resize', () => onWindowResize(div));
	renderer.domElement.addEventListener('pointermove', (event) => onPointerMove(event, div, constraints));
	renderer.domElement.addEventListener('pointerdown', (event) => onPointerDown(event));
	renderer.domElement.addEventListener('pointerup', onPointerUp);

	animate();
}

function onPointerMove(event: PointerEvent, div: HTMLDivElement, constraints: AxisConstraints) {
	const intersects = getIntersects(event);

	if (!isDragging) {
		resetHighlight();
		if (intersects.length > 0) {
			const face = intersects[0].face!;
			const materialIndex = face.materialIndex!;

			// 하이라이트 적용
			if (hoveredFaceIndex !== materialIndex) {
				hoveredFaceIndex = materialIndex;
				(cube.material as THREE.Material[])[materialIndex] = highlightMaterial;
				(cube.material as THREE.Material[]).needsUpdate = true;
			}
		}
	} else if (selectedFaceNormal) {
		// 마우스 이동 거리 계산 (픽셀 단위)
		const rect = renderer.domElement.getBoundingClientRect();
		const currentMouseX = event.clientX - rect.left;
		const currentMouseY = event.clientY - rect.top;
		const dx = (currentMouseX - startMouseX) / rect.width;
		const dy = (currentMouseY - startMouseY) / rect.height;

		const scaleFactor = 2 * camera.position.distanceTo(cube.position);
		let dragAmount = (dx - dy) * scaleFactor;

		const scaleDir = selectedFaceNormal.clone().normalize();
		const newScale = startScale.clone();
		const newPosition = startPosition.clone();

		if (Math.abs(scaleDir.y) > 0.9) {
			if (scaleDir.y > 0) {
				scaleDir.y *= 0.5;
				newScale.y = Math.max(constraints.y.min, Math.min(constraints.y.max, startScale.y + dragAmount));
				newPosition.y = startPosition.y + (newScale.y - startScale.y) / 2;
			} else {
				newScale.y = Math.max(constraints.y.min, Math.min(constraints.y.max, startScale.y - dragAmount));
				newPosition.y = startPosition.y - (newScale.y - startScale.y) / 2;
			}
		} else {
			if (Math.abs(scaleDir.z) > 0.9) {
				dragAmount = -dragAmount;
			}
			newScale.add(scaleDir.multiplyScalar(dragAmount));
			newScale.x = Math.max(constraints.x.min, Math.min(constraints.x.max, newScale.x));
			newScale.y = Math.max(constraints.y.min, Math.min(constraints.y.max, newScale.y));
			newScale.z = Math.max(constraints.z.min, Math.min(constraints.z.max, newScale.z));
		}

		cube.scale.copy(newScale);
		cube.position.copy(newPosition);
	}
}

function onPointerDown(event: PointerEvent) {
	const intersects = getIntersects(event);
	if (intersects.length > 0) {
		const face = intersects[0].face;
		if (!face) return;

		// 드래그 시작
		isDragging = true;
		const rect = renderer.domElement.getBoundingClientRect();
		startMouseX = event.clientX - rect.left;
		startMouseY = event.clientY - rect.top;
		startScale.copy(cube.scale);
		startPosition.copy(cube.position);

		// 면의 노멀 방향 저장 (World 기준)
		selectedFaceNormal = face.normal.clone().transformDirection(cube.matrixWorld).normalize();

		// Orbit 끄기
		orbit.enabled = false;
	}
}

function onPointerUp() {
	isDragging = false;
	selectedFaceNormal = null;
	orbit.enabled = true;
}

function resetHighlight() {
	if (hoveredFaceIndex !== null) {
		(cube.material as THREE.Material[])[hoveredFaceIndex] = baseMaterial;
		(cube.material as THREE.Material[]).needsUpdate = true;
		hoveredFaceIndex = null;
	}
}

function getIntersects(event: PointerEvent) {
	const rect = renderer.domElement.getBoundingClientRect();
	mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
	mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
	raycaster.setFromCamera(mouse, camera);
	return raycaster.intersectObject(cube, false);
}

function onWindowResize(div: HTMLDivElement) {
	camera.aspect = div.clientWidth / div.clientHeight;
	camera.updateProjectionMatrix();
	renderer.setSize(div.clientWidth, div.clientHeight);
}

function animate() {
	requestAnimationFrame(animate);
	orbit.update();
	renderer.render(scene, camera);
}

export class Solution {
	constructor(id: string = 'main', constraints?: AxisConstraints) {
		const div = document.getElementById(id) as HTMLDivElement;
		init(div, constraints);
	}
}
